import time
import flaky

def with_retry(fn, tries=4, base=0.1):
    for i in range(tries):
        try:
            return fn()
        except Exception:
            if i == tries - 1:
                raise
            d = base * 2 ** i
            open('sleeps.txt','a').write(f'{d}\n')
            time.sleep(d)

open('sleeps.txt','w').close()
print(with_retry(flaky.work))
EOF
